after.content:
var first = executor.submit(() -> coordinator.completeAuthorizationCode(transaction.sessionId(), "device-a",
        state, code(), CancellationToken.NONE));
assertTrue(provider.entered.await(2, TimeUnit.SECONDS));
var second = executor.submit(() -> {
    try {
        coordinator.completeAuthorizationCode(transaction.sessionId(), "device-a", state, code(), CancellationToken.NONE);
        return null;
    } catch (RuntimeException exception) {
        return exception;
    }
});
Throwable secondFailure = second.get(2, TimeUnit.SECONDS);
assertInstanceOf(JiException.class, secondFailure);
assertEquals(ErrorCode.OAUTH_REPLAYED, ((JiException) secondFailure).error().code());
